package com.acme.cli.auth

import java.security.MessageDigest
import java.time.{Clock, Instant, Duration}
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.concurrent.TrieMap

object AuthConfig {
  val SERVICE_SECRET: String = sys.env.getOrElse("SERVICE_SECRET", "default-dev-key")
  val SIGNATURE_VALIDITY_WINDOW: Duration = Duration.ofMinutes(5)
  val clock: Clock = Clock.systemUTC()
}

case class AuthToken(
  serviceId: String,
  targetService: String,
  timestamp: Long,
  nonce: String,
  signature: String
)

object SignatureEngine {
  private val usedNonces: TrieMap[String, Long] = TrieMap.empty
  private val NONCE_CLEANUP_THRESHOLD = 10000

  def generateSignature(serviceId: String, targetService: String, timestamp: Long, nonce: String): String = {
    val payload = s"$serviceId|$targetService|$timestamp|$nonce"
    computeHmac(payload, AuthConfig.SERVICE_SECRET)
  }

  def computeHmac(data: String, secret: String): String = {
    val algorithm = "HmacSHA256"
    val mac = Mac.getInstance(algorithm)
    val keySpec = new SecretKeySpec(secret.getBytes("UTF-8"), algorithm)
    mac.init(keySpec)
    val rawHmac = mac.doFinal(data.getBytes("UTF-8"))
    Base64.getEncoder.encodeToString(rawHmac)
  }

  def createToken(serviceId: String, targetService: String): AuthToken = {
    val timestamp = Instant.now(AuthConfig.clock).getEpochSecond
    val nonce = java.util.UUID.randomUUID().toString
    val signature = generateSignature(serviceId, targetService, timestamp, nonce)
    AuthToken(serviceId, targetService, timestamp, nonce, signature)
  }

  private def cleanupNonces(): Unit = {
    if (usedNonces.size > NONCE_CLEANUP_THRESHOLD) {
      val cutoff = Instant.now(AuthConfig.clock).getEpochSecond - AuthConfig.SIGNATURE_VALIDITY_WINDOW.getSeconds * 2
      usedNonces.filterInPlace((_, ts) => ts > cutoff)
    }
  }

  def recordNonce(nonce: String, timestamp: Long): Boolean = {
    cleanupNonces()
    usedNonces.putIfAbsent(nonce, timestamp).isEmpty
  }
}

object TokenValidator {
  def validateToken(token: AuthToken, expectedTarget: String): Either[String, String] = {
    // Step 1: Verify target service
    if (token.targetService != expectedTarget) {
      return Left(s"Token not intended for service: $expectedTarget")
    }

    // Step 2: Verify timestamp is within validity window
    val now = Instant.now(AuthConfig.clock).getEpochSecond
    val elapsed = Math.abs(now - token.timestamp)
    if (elapsed > AuthConfig.SIGNATURE_VALIDITY_WINDOW.getSeconds) {
      return Left("Token has expired")
    }

    // Step 3: Verify signature
    val expectedSig = SignatureEngine.generateSignature(
      token.serviceId, token.targetService, token.timestamp, token.nonce
    )
    if (!constantTimeEquals(expectedSig, token.signature)) {
      return Left("Invalid signature")
    }

    // Step 4: Check nonce for replay protection
    val nonceKey = buildNonceKey(token)
    if (!SignatureEngine.recordNonce(nonceKey, token.timestamp)) {
      return Left("Nonce already used - possible replay")
    }

    Right(token.serviceId)
  }

  private def buildNonceKey(token: AuthToken): String = {
    // Include service context in nonce key to prevent cross-service confusion
    s"${token.serviceId}:${token.nonce}"
  }

  private def constantTimeEquals(a: String, b: String): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    for (i <- a.indices) {
      result |= a.charAt(i) ^ b.charAt(i)
    }
    result == 0
  }
}

object CrossServiceAuth {
  def authenticateRequest(rawToken: String, myServiceId: String): Either[String, String] = {
    parseToken(rawToken).flatMap { token =>
      TokenValidator.validateToken(token, myServiceId)
    }
  }

  def parseToken(raw: String): Either[String, AuthToken] = {
    val parts = raw.split("\\|")
    if (parts.length != 5) {
      Left("Malformed token")
    } else {
      try {
        Right(AuthToken(
          serviceId = parts(0),
          targetService = parts(1),
          timestamp = parts(2).toLong,
          nonce = parts(3),
          signature = parts(4)
        ))
      } catch {
        case _: NumberFormatException => Left("Invalid timestamp in token")
      }
    }
  }

  def issueToken(fromService: String, toService: String): String = {
    val token = SignatureEngine.createToken(fromService, toService)
    s"${token.serviceId}|${token.targetService}|${token.timestamp}|${token.nonce}|${token.signature}"
  }
}

object CliMain extends App {
  val action = args.headOption.getOrElse("help")
  action match {
    case "issue" =>
      val from = args(1)
      val to = args(2)
      println(CrossServiceAuth.issueToken(from, to))
    case "verify" =>
      val token = args(1)
      val myId = args(2)
      CrossServiceAuth.authenticateRequest(token, myId) match {
        case Right(caller) => println(s"Authenticated: $caller")
        case Left(err) => System.err.println(s"Auth failed: $err"); sys.exit(1)
      }
    case _ =>
      println("Usage: cli [issue <from> <to>] | [verify <token> <myServiceId>]")
  }
}
